import React, { useEffect } from "react";
import { BrowserRouter, Routes, Route, Navigate } from "react-router-dom";
import Login from "./components/login";
import Signup from "./components/signup";
import Home from "./pages/home";
import Products from "./pages/products";
import Category from "./pages/category";
import Brand from "./pages/brand";

import PrivateRoute from "./components/PrivateRoute";
import PublicRoute from "./components/PublicRoute";
import Layout from "./components/layout";
import NavigationGuard from "./components/NavigationGuard";

import "./product.css";
import "./components/header.css";
import "./components/fotter.css";

function App() {
  const token = localStorage.getItem("token");

  useEffect(() => {
    const setAllowNavigation = () => {
      sessionStorage.setItem("allowNavigation", "true");
    };
    window.addEventListener("click", setAllowNavigation, true);
    return () => window.removeEventListener("click", setAllowNavigation, true);
  }, []);

  return (
    <BrowserRouter>
      <NavigationGuard>
        <Routes>
          {/* Public Routes (No Header) */}
          <Route
            path="/login"
            element={
              <PublicRoute>
                <Login />
              </PublicRoute>
            }
          />
          <Route
            path="/signup"
            element={
              <PublicRoute>
                <Signup />
              </PublicRoute>
            }
          />
          <Route
            path="/"
            element={<Navigate to={token ? "/home" : "/login"} replace />}
          />

          {/* Private Routes with Header (inside Layout) */}
          <Route
            element={
              <PrivateRoute>
                <Layout />
              </PrivateRoute>
            }
          >
            <Route path="/home" element={<Home />} />
            <Route path="/products" element={<Products />} />
            <Route path="/category" element={<Category />} />
            <Route path="/brand" element={<Brand />} />
          </Route>

          {/* Fallback route */}
          <Route
            path="*"
            element={<Navigate to={token ? "/home" : "/login"} replace />}
          />
        </Routes>
      </NavigationGuard>
    </BrowserRouter>
  );
}

export default App;
